#include "gravity_model.h"
#include <math.h>

/* Generated by fit_gravity_2axis.py. Inputs rad, outputs Nm.
 * 1, sin(q1), cos(q1), sin(q1+q2), cos(q1+q2), sin(q2), cos(q2). */
static const float coeff[2][7] = {
    {-1.689262028e+00f, 1.015345099e+00f, 1.434031016e+00f, -4.709345050e-01f, -5.859420837e-01f, 2.286407447e-01f, 1.173890309e+00f},
    {8.708525627e-01f, -4.900805537e-01f, -1.305387010e+00f, 6.751437249e-01f, 7.335953297e-01f, -2.705571880e-01f, -1.306608426e-01f}
};

void gravity_model_eval(const float q_rad[2], float torque_nm[2])
{
    float f[7];
    unsigned int i, j;
    f[0] = 1.0f;
    f[1] = sinf(q_rad[0]);
    f[2] = cosf(q_rad[0]);
    f[3] = sinf(q_rad[0] + q_rad[1]);
    f[4] = cosf(q_rad[0] + q_rad[1]);
    f[5] = sinf(q_rad[1]);
    f[6] = cosf(q_rad[1]);
    for (i = 0U; i < 2U; ++i) {
        float value = 0.0f;
        for (j = 0U; j < 7U; ++j) value += coeff[i][j] * f[j];
        torque_nm[i] = value;
    }
}
